// Компоненты Jinx UI подобраны по документированной модели value/onValueChange; уточните имена пропсов JxPagination/JxBadge по вашей версии пакета.
import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxPagination,
  JxTable,
  JxTableBody,
  JxTableCell,
  JxTableHead,
  JxTableHeaderCell,
  JxTableRow,
} from '@jinx-ui/react';

const PAGE_SIZE = 10;

export interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

export interface UsersTableProps {
  users: User[];
}

function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <div style={{ display: 'grid', gap: 'var(--jx-space-4)' }}>
      <JxTable>
        <JxTableHead>
          <JxTableRow>
            <JxTableHeaderCell>Имя</JxTableHeaderCell>
            <JxTableHeaderCell>Роль</JxTableHeaderCell>
            <JxTableHeaderCell>Статус</JxTableHeaderCell>
          </JxTableRow>
        </JxTableHead>
        <JxTableBody>
          {rows.length === 0 ? (
            <JxTableRow>
              <JxTableCell colSpan={3}>Пользователей нет</JxTableCell>
            </JxTableRow>
          ) : (
            rows.map((user) => (
              <JxTableRow key={user.id}>
                <JxTableCell>{user.name}</JxTableCell>
                <JxTableCell>{user.role}</JxTableCell>
                <JxTableCell>
                  <JxBadge variant={user.active ? 'success' : 'neutral'}>
                    {user.active ? 'Активен' : 'Отключён'}
                  </JxBadge>
                </JxTableCell>
              </JxTableRow>
            ))
          )}
        </JxTableBody>
      </JxTable>

      {pageCount > 1 && (
        <JxPagination value={currentPage} onValueChange={setPage} count={pageCount} />
      )}
    </div>
  );
}

export default UsersTable;

